 import { Blob } from '@google/genai';
import { OUTPUT_AUDIO_SAMPLE_RATE } from '../constants';

/**
 * Encodes a Uint8Array to a base64 string.
 * This is a  custom implementation required by the GenAI SDK, not js-base64.
 * @param bytes The Uint8Array to encode.
 * @returns Base64 encoded string.
 */
export function encode(bytes: Uint 8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[ i]);
  }
  return btoa(binary);
}

/**
 * Decodes a base64 string into a Uint8Array.
 * This is a custom implementation required by the GenAI SDK, not js-
 * base64.
 * @param base64 Base64 encoded string.
 * @returns Uint8Array.
 */
export function decode(base64: string): Uint8Array {
  const binary = atob(base64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[ i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * Gets the output audio context. Creates one if it doesn't exist.
 * @returns The output audio context.
 */
export function getOutputAudioContext(): AudioContext {
  if (!window.outputAudioContext) {
    window.outputAudioContext = new AudioContext({
      latencyHint: 'interactive',
      sampleRate: OUTPUT_AUDIO_SAMPLE_RATE,
    });
  }
  return window.outputAudioContext;
}

let audioSources = new Set<AudioBufferSourceNode>(); // Track all actively playing buffers

/**
 * Stops all currently playing audio.
 */
export function stopAllAudio() {
  audioSources.forEach((source) => {
    source.stop();
    source.disconnect();
  });
  audioSources.clear();
}

/**
 * Plays an audio buffer once.
 * @param audioBuffer The audio buffer to play.
 */
export function playSingleAudioBuffer(audioBuffer: AudioBuffer) {
  const ctx = getOutputAudioContext();
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination);
  source.addEventListener('ended', () => {
    audioSources.delete(source);
  });
  source.start(ctx.currentTime);
  audioSources.add(source);
}
    ]]></content>
