import { Blob as GenAIBlob } from '@google/genai'; // Renamed to avoid conflict with DOM Blob
import { OUTPUT_AUDIO_SAMPLE_RATE } from '../constants';

/**
 * Encodes a Uint8Array to a base64 string.
 * This is a custom implementation required by the GenAI SDK, not js-base64.
 * @param bytes The Uint8Array to encode.
 * @returns Base64 encoded string.
 */
export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

/**
 * Decodes a base64 string into a Uint8Array.
 * This is a custom implementation required by the GenAI SDK, not js-base64.
 * @param base64 The base64 string to decode.
 * @returns Decoded Uint8Array.
 */
export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Decodes raw PCM audio data into an AudioBuffer suitable for Web Audio API playback.
 * This is a custom implementation required by the GenAI SDK for raw PCM.
 * @param data Raw PCM audio data as Uint8Array.
 * @param ctx AudioContext to create the buffer.
 * @param sampleRate Sample rate of the audio data.
 * @param numChannels Number of audio channels.
 * @returns Promise resolving to an AudioBuffer.
 */
export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

/**
 * Creates a Blob object for audio input, encoding Float32Array to Int16Array PCM.
 * @param data Audio data as Float32Array.
 * @param sampleRate Sample rate of the audio (e.g., 16000 for Live API).
 * @returns GenAIBlob object with base64 encoded PCM data.
 */
export function createAudioBlob(data: Float32Array, sampleRate: number): GenAIBlob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768; // Convert float to 16-bit signed integer
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: `audio/pcm;rate=${sampleRate}`,
  };
}

// Global variable to hold the output audio context
let outputAudioContext: AudioContext | null = null;

// Initialize and return the singleton output AudioContext
export function getOutputAudioContext(): AudioContext {
  if (!outputAudioContext) {
    // Initializes a new AudioContext for output audio, ensuring deprecated `window.webkitAudioContext` is not used.
    outputAudioContext = new window.AudioContext({
      sampleRate: OUTPUT_AUDIO_SAMPLE_RATE,
    });
  }
  return outputAudioContext;
}

// Function to stop all playing audio sources
let audioSources = new Set<AudioBufferSourceNode>();
export function stopAllAudio() {
  for (const source of audioSources.values()) {
    try {
      source.stop();
    } catch (error) {
      // console.warn('Error stopping audio source:', error);
    }
  }
  audioSources.clear();
}

// Function to play audio buffer
let nextStartTime = 0; // Global to ensure sequential playback
export async function playAudioBuffer(audioBuffer: AudioBuffer) {
  const ctx = getOutputAudioContext();
  nextStartTime = Math.max(nextStartTime, ctx.currentTime);

  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination); // Connect directly to destination for playback

  source.addEventListener('ended', () => {
    audioSources.delete(source);
  });

  source.start(nextStartTime);
  nextStartTime += audioBuffer.duration;
  audioSources.add(source);
}

/**
 * Creates a WAV Blob from raw 16-bit PCM audio data.
 * @param pcmData 16-bit PCM audio data as Uint8Array.
 * @param sampleRate Sample rate of the audio.
 * @param numChannels Number of audio channels.
 * @returns A Blob object representing the WAV file.
 */
export function createWavBlobFromPCM(
  pcmData: Uint8Array,
  sampleRate: number,
  numChannels: number,
): Blob {
  const HEADER_LENGTH = 44; // Standard WAV header length
  const dataLength = pcmData.byteLength;
  const buffer = new ArrayBuffer(HEADER_LENGTH + dataLength);
  const view = new DataView(buffer);

  // RIFF chunk descriptor
  writeString(view, 0, 'RIFF'); // Chunk ID
  view.setUint32(4, 36 + dataLength, true); // Chunk size
  writeString(view, 8, 'WAVE'); // Format

  // FMT sub-chunk
  writeString(view, 12, 'fmt '); // Subchunk1 ID
  view.setUint32(16, 16, true); // Subchunk1 size (16 for PCM)
  view.setUint16(20, 1, true); // Audio format (1 for PCM)
  view.setUint16(22, numChannels, true); // Num channels
  view.setUint32(24, sampleRate, true); // Sample rate
  view.setUint32(28, sampleRate * numChannels * 2, true); // Byte rate (SampleRate * NumChannels * BytesPerSample)
  view.setUint16(32, numChannels * 2, true); // Block align (NumChannels * BytesPerSample)
  view.setUint16(34, 16, true); // Bits per sample (16 for Int16Array)

  // DATA sub-chunk
  writeString(view, 36, 'data'); // Subchunk2 ID
  view.setUint32(40, dataLength, true); // Subchunk2 size

  // Write PCM data
  const pcmView = new Uint8Array(buffer, HEADER_LENGTH);
  pcmView.set(pcmData);

  return new Blob([view], { type: 'audio/wav' });
}

// Helper function to write a string to DataView
function writeString(view: DataView, offset: number, s: string) {
  for (let i = 0; i < s.length; i++) {
    view.setUint8(offset + i, s.charCodeAt(i));
  }
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Greeting } from '../types';
import Button from './Button';
import { getOutputAudioContext, playAudioBuffer, decodeAudioData, decode, stopAllAudio, createWavBlobFromPCM } from '../utils/audioUtils';
import { OUTPUT_AUDIO_SAMPLE_RATE } from '../constants';

interface GreetingCardProps {
  greeting: Greeting;
  onDelete: (id: string) => void;
}

const GreetingCard: React.FC<GreetingCardProps> = ({ greeting, onDelete }) => {
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [showVideoPlayer, setShowVideoPlayer] = useState(false); // New state for video player visibility
  const [videoPlaybackLoading, setVideoPlaybackLoading] = useState(false); // New state for video loading spinner
  const audioRef = useRef<HTMLAudioElement | null>(null); // For native audio playback (not currently used for PCM)
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [videoError, setVideoError] = useState<string | null>(null);
  const videoLoadTimeoutRef = useRef<number | null>(null);

  // Internal helper to play audio without managing `isPlayingAudio` state directly
  const _playAudioInternal = useCallback(async () => {
    if (!greeting.audioUrl) {
      console.warn("No audio URL available for playback.");
      return;
    }

    // If it's a data URL, decode and play as PCM
    if (greeting.audioUrl.startsWith('data:audio/pcm;base64,')) {
      const base64Audio = greeting.audioUrl.split(',')[1];
      try {
        const audioBuffer = await decodeAudioData(
          decode(base64Audio),
          getOutputAudioContext(),
          OUTPUT_AUDIO_SAMPLE_RATE,
          1
        );
        await playAudioBuffer(audioBuffer); // This manages global audio sources
      } catch (error) {
        console.error('Error playing PCM audio internally:', error);
        throw error;
      }
    } else {
      // Fallback for standard audio formats if ever generated (not current setup)
      if (audioRef.current) {
        audioRef.current.src = greeting.audioUrl;
        await audioRef.current.play().catch(e => {
          console.error("Error playing audio internally (native):", e);
          throw e;
        });
      }
    }
  }, [greeting.audioUrl]);

  // Function to play/pause audio (for standalone audio button)
  const handlePlayAudio = useCallback(async () => {
    stopAllAudio(); // Stop all existing audio, including any video-synced audio
    if (videoRef.current && !videoRef.current.paused) {
      videoRef.current.pause(); // Pause video if playing
    }
    setVideoError(null); // Clear video error if playing audio separately
    setIsPlayingAudio(true);
    setShowVideoPlayer(false); // Hide video player if audio is played separately
    setVideoPlaybackLoading(false); // Ensure video loading is off

    try {
      await _playAudioInternal();
    } catch (e) {
      setIsPlayingAudio(false);
      console.error("Failed to play audio:", e);
    }
    // We don't set isPlayingAudio to false here on audio `ended` event.
    // This is handled by a global listener in `audioUtils.ts` or when another media starts/stops.
  }, [_playAudioInternal]);

  const handlePauseAudio = useCallback(() => {
    stopAllAudio(); // Stop custom PCM playback
    if (audioRef.current) {
      audioRef.current.pause(); // Stop native HTML audio
    }
    setIsPlayingAudio(false);
  }, []);

  // Function to play video and simultaneously start audio
  const handlePlayVideo = useCallback(async () => {
    stopAllAudio(); // Stop any standalone audio playback
    if (audioRef.current) {
      audioRef.current.pause(); // Stop native HTML audio
    }
    setIsPlayingAudio(false); // Reset audio state
    setVideoError(null); // Clear previous video error
    setShowVideoPlayer(true); // Show the video player
    setVideoPlaybackLoading(true); // Start video loading spinner

    // Clear any previous timeout
    if (videoLoadTimeoutRef.current) {
      clearTimeout(videoLoadTimeoutRef.current);
      videoLoadTimeoutRef.current = null;
    }

    // A small delay to ensure the video element is rendered before attempting to load
    setTimeout(() => {
      if (videoRef.current) {
        const videoElement = videoRef.current;
        videoElement.load(); // Ensure video is loaded

        const startBothPlayback = async () => {
          if (videoLoadTimeoutRef.current) {
            clearTimeout(videoLoadTimeoutRef.current);
            videoLoadTimeoutRef.current = null;
          }
          setVideoPlaybackLoading(false); // Hide loading spinner

          // Start audio first
          if (greeting.audioUrl) {
            try {
              await _playAudioInternal();
            } catch (e) {
              console.error("Error starting synchronized audio for video:", e);
              // Don't block video playback, but log the error
            }
          }

          // Then start video
          videoElement.play().catch(e => {
            console.error("Error playing video:", e);
            setVideoError(`Could not play video: ${e.message}. Ensure your browser allows autoplay or try clicking play manually.`);
          });
          videoElement.requestFullscreen().catch(e => {
            console.warn("Could not enter fullscreen:", e);
          });
        };

        const onVideoCanPlayThrough = () => {
          videoElement.removeEventListener('canplaythrough', onVideoCanPlayThrough);
          startBothPlayback();
        };

        videoElement.addEventListener('canplaythrough', onVideoCanPlayThrough);

        // Fallback timeout in case 'canplaythrough' doesn't fire or takes too long
        videoLoadTimeoutRef.current = window.setTimeout(() => {
          videoElement.removeEventListener('canplaythrough', onVideoCanPlayThrough);
          console.warn("Video 'canplaythrough' timeout, attempting to play anyway.");
          startBothPlayback();
        }, 10000); // 10 seconds timeout
      }
    }, 50); // Small initial delay to ensure render
  }, [greeting.audioUrl, _playAudioInternal]);


  const handleCloseVideoPlayer = useCallback(() => {
    if (videoLoadTimeoutRef.current) {
      clearTimeout(videoLoadTimeoutRef.current);
      videoLoadTimeoutRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.pause(); // Pause video when closing
      // Ensure the 'canplaythrough' listener is removed if it was pending
      videoRef.current.removeEventListener('canplaythrough', () => {}); // Remove any pending listeners
      if (document.fullscreenElement === videoRef.current) {
        document.exitFullscreen().catch(e => console.warn("Could not exit fullscreen:", e));
      }
    }
    stopAllAudio(); // Stop any audio that was playing with the video
    if (audioRef.current) {
      audioRef.current.pause(); // Stop native HTML audio
    }
    setIsPlayingAudio(false); // Reset audio state
    setShowVideoPlayer(false);
    setVideoPlaybackLoading(false); // Reset video loading state
    setVideoError(null);
  }, []);

  useEffect(() => {
    // Event listener for native <audio> element to update state (if ever used)
    const audioEl = audioRef.current;
    if (audioEl) {
      const onEnded = () => setIsPlayingAudio(false);
      const onPlay = () => setIsPlayingAudio(true);
      const onPause = () => setIsPlayingAudio(false);
      audioEl.addEventListener('ended', onEnded);
      audioEl.addEventListener('play', onPlay);
      audioEl.addEventListener('pause', onPause);
      return () => {
        audioEl.removeEventListener('ended', onEnded);
        audioEl.removeEventListener('play', onPlay);
        audioEl.removeEventListener('pause', onPause);
      };
    }

    // Cleanup video player state if greeting changes or component unmounts
    return () => {
      handleCloseVideoPlayer(); // Ensure video is paused and hidden
    };
  }, [greeting.id, handleCloseVideoPlayer]); // Re-run effect if greeting ID changes

  const formattedDate = new Date(greeting.createdAt).toLocaleString();

  // Handle video loading errors
  const handleVideoError = useCallback((event: React.SyntheticEvent<HTMLVideoElement, Event>) => {
    console.error("Video element error:", event);
    setVideoError("Failed to load video. It might be unavailable or corrupt, or network issues prevented loading. The AI-generated video does not include embedded audio; the audio plays alongside.");
    setVideoPlaybackLoading(false); // Hide loading spinner on error
    setShowVideoPlayer(true); // Keep player visible to show error message
  }, []);

  const handleDownloadVideo = useCallback(() => {
    if (greeting.videoUrl) {
      const link = document.createElement('a');
      link.href = greeting.videoUrl;
      link.download = `eGreetz_video_${greeting.id}.mp4`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  }, [greeting.videoUrl, greeting.id]);

  const handleDownloadAudio = useCallback(() => {
    if (greeting.audioUrl && greeting.audioUrl.startsWith('data:audio/pcm;base64,')) {
      try {
        const base64Audio = greeting.audioUrl.split(',')[1];
        const pcmData = decode(base64Audio);
        const wavBlob = createWavBlobFromPCM(pcmData, OUTPUT_AUDIO_SAMPLE_RATE, 1);

        const link = document.createElement('a');
        link.href = URL.createObjectURL(wavBlob);
        link.download = `eGreetz_audio_${greeting.id}.wav`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(link.href); // Clean up the Blob URL
      } catch (error) {
        console.error('Error downloading audio:', error);
        alert('Failed to download audio. Please try again.');
      }
    } else {
      alert('No downloadable audio available in the correct format.');
    }
  }, [greeting.audioUrl, greeting.id]);


  return (
    <div className="relative bg-gray-800 rounded-lg shadow-xl p-6 mb-6 border border-gray-700 overflow-hidden">
      <h3 className="text-3xl font-bold text-center text-indigo-300 mb-4">{greeting.occasion}</h3>
      <p className="text-gray-300 text-center text-sm mb-2">Created: {formattedDate}</p>

      {greeting.imageUrl && (
        <div className="mb-4 flex justify-center">
          <img
            src={greeting.imageUrl}
            alt="User Upload"
            className="max-w-full h-auto max-h-64 object-cover rounded-md shadow-md border border-gray-600"
            loading="lazy"
          />
        </div>
      )}

      <p className="text-gray-200 text-lg mb-4 text-center">{greeting.message}</p>

      <div className="flex flex-col sm:flex-row justify-center gap-4 mt-4">
        {greeting.audioUrl && (
          <Button onClick={isPlayingAudio ? handlePauseAudio : handlePlayAudio} className="w-full sm:w-auto">
            {isPlayingAudio ? (
              <>
                <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg> Pause Audio
              </>
            ) : (
              <>
                <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                </svg> Play Audio
              </>
            )}
          </Button>
        )}

        {greeting.videoUrl && (
          <Button
            onClick={handlePlayVideo} // Use the new handler
            className="w-full sm:w-auto"
            aria-controls={`video-player-${greeting.id}`}
            disabled={videoPlaybackLoading} // Disable button while loading
          >
            {videoPlaybackLoading ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg> Loading Video...
              </>
            ) : (
              <>
                <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path d="M2 6a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2h-4a2 2 0 01-2-2V6zM2 14a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2H4a2 2 0 01-2-2v-2zM14 14a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2h-4a2 2 0 01-2-2v-2z" />
                </svg>
                Play Cinematic Video
              </>
            )}
          </Button>
        )}
      </div>

      {showVideoPlayer && greeting.videoUrl && (
        <div className="mt-4 p-4 bg-gray-900 rounded-lg relative min-h-[200px] flex items-center justify-center">
          {videoPlaybackLoading && (
            <div className="absolute inset-0 bg-gray-800 bg-opacity-90 flex flex-col items-center justify-center rounded-lg z-10">
              <svg className="animate-spin h-8 w-8 text-white mb-3" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <p className="text-white text-lg">Buffering video for synchronized playback...</p>
              <p className="text-gray-400 text-sm mt-1">This ensures audio and video start together. Note: The video itself does not contain embedded audio.</p>
            </div>
          )}
          {videoError && (
            <div className="absolute inset-0 bg-red-900 bg-opacity-90 border border-red-700 text-red-200 px-4 py-3 rounded-lg flex flex-col items-center justify-center text-center z-10" role="alert">
              <strong className="font-bold">Video Error:</strong>
              <span className="block sm:inline ml-2">{videoError}</span>
              <p className="text-sm mt-2">The AI-generated video does not include embedded audio. The audio plays simultaneously alongside the video. Please check your browser's console for more details.</p>
              <button
                onClick={handleCloseVideoPlayer}
                className="mt-4 bg-gray-700 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded-md transition-colors duration-200"
                aria-label="Close error message"
              >
                Close Error
              </button>
            </div>
          )}
          <video
            ref={videoRef}
            id={`video-player-${greeting.id}`}
            src={greeting.videoUrl}
            controls
            className={`w-full max-w-lg mx-auto rounded-md shadow-lg ${videoPlaybackLoading || videoError ? 'invisible' : ''}`}
            aria-label="Cinematic greeting video player"
            onError={handleVideoError}
            preload="auto" // Suggest browser to preload video
          ></video>
          <div className="flex justify-center mt-4">
            <Button
              onClick={handleCloseVideoPlayer}
              variant="secondary"
              className="w-full sm:w-auto"
              aria-label="Close video player"
              disabled={videoPlaybackLoading}
            >
              Close Video
            </Button>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-center gap-4 mt-6 border-t border-gray-700 pt-6">
        {greeting.videoUrl && (
          <Button
            onClick={handleDownloadVideo}
            variant="secondary"
            className="w-full sm:w-auto"
            aria-label="Download generated video"
            title="Download Video (No Audio)"
          >
            <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L10 11.586l2.293-2.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
              <path fillRule="evenodd" d="M10 2a1 1 0 011 1v7a1 1 0 11-2 0V3a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
            Download Video
          </Button>
        )}
        {greeting.audioUrl && (
          <Button
            onClick={handleDownloadAudio}
            variant="secondary"
            className="w-full sm:w-auto"
            aria-label="Download generated audio"
            title="Download Audio (WAV)"
          >
            <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L10 11.586l2.293-2.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
              <path fillRule="evenodd" d="M10 2a1 1 0 011 1v7a1 1 0 11-2 0V3a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
            Download Audio
          </Button>
        )}
      </div>


      <div className="absolute bottom-2 left-2 text-gray-500 text-xs italic opacity-80">
        created by e-Greetz
      </div>

      <Button
        onClick={() => greeting.id && onDelete(greeting.id)}
        variant="danger"
        className="absolute top-4 right-4 p-2 rounded-full text-sm"
        aria-label={`Delete greeting for ${greeting.occasion}`}
        title="Delete Greeting"
      >
        <svg className="h-4 w-4" fill="currentColor" viewBox="0 0 20 20">
          <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm6 0a1 1 0 11-2 0v6a1 1 0 112 0V8z" clipRule="evenodd" />
        </svg>
      </Button>
      {/* Hidden audio element for browser's native controls (e.g., for non-PCM audio, not currently used) */}
      <audio ref={audioRef} className="hidden" onEnded={() => setIsPlayingAudio(false)}></audio>
    </div>
  );
};

export default GreetingCard;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import Button from './Button';
import { Greeting, VoiceGender, VoiceType } from '../types';
import {
  GREETING_OCCASIONS,
  VOICE_OPTIONS,
  getVoiceConfig,
  VIDEO_BACKGROUND_PROMPTS,
  MAX_MESSAGE_LENGTH,
  AUDIO_SAMPLE_RATE,
  OUTPUT_AUDIO_SAMPLE_RATE,
} from '../constants';
import * as firebaseService from '../services/firebaseService';
import {
  GoogleGenAI,
  Modality,
  LiveServerMessage,
  VideoGenerationReferenceType,
} from '@google/genai';
import {
  encode,
  decode,
  decodeAudioData,
  createAudioBlob,
  getOutputAudioContext,
  playAudioBuffer,
  stopAllAudio,
} from '../utils/audioUtils';
import { fileToBase64 } from '../utils/imageUtils';

interface GreetingFormProps {
  onGreetingCreated: (greeting: Greeting) => void;
  getGenAIInstance: () => GoogleGenAI;
  onApiKeyPrompt: () => void;
}

const GreetingForm: React.FC<GreetingFormProps> = ({
  onGreetingCreated,
  getGenAIInstance,
  onApiKeyPrompt,
}) => {
  const [occasion, setOccasion] = useState(GREETING_OCCASIONS[0]);
  const [message, setMessage] = useState('');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [previewImageUrl, setPreviewImageUrl] = useState<string | null>(null);
  const [voiceGender, setVoiceGender] = useState<VoiceGender>(VoiceGender.Male);
  const [voiceType, setVoiceType] = useState<VoiceType>(
    VOICE_OPTIONS[VoiceGender.Male][0].value
  );

  const [isRecording, setIsRecording] = useState(false);
  const [audioStream, setAudioStream] = useState<MediaStream | null>(null);
  const [audioChunks, setAudioChunks] = useState<Float32Array[]>([]);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const liveSessionRef = useRef<Promise<any> | null>(null); // To hold the promise of the live session

  const [loadingAudio, setLoadingAudio] = useState(false);
  const [loadingVideo, setLoadingVideo] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [videoGenerationMessage, setVideoGenerationMessage] = useState<string | null>(null);

  // AudioContext for microphone input
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const resetForm = useCallback(() => {
    setOccasion(GREETING_OCCASIONS[0]);
    setMessage('');
    setImageFile(null);
    setPreviewImageUrl(null);
    setVoiceGender(VoiceGender.Male);
    setVoiceType(VOICE_OPTIONS[VoiceGender.Male][0].value);
    setIsRecording(false);
    setAudioChunks([]);
    setError(null);
    setVideoGenerationMessage(null);
    stopAllAudio(); // Stop any playing audio
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    if (audioStream) {
      audioStream.getTracks().forEach((track) => track.stop());
      setAudioStream(null);
    }
    if (liveSessionRef.current) {
      liveSessionRef.current.then((session: any) => session.close());
      liveSessionRef.current = null;
    }
  }, [audioStream]);

  // Handle voice type options changing with gender
  useEffect(() => {
    const defaultVoice = VOICE_OPTIONS[voiceGender][0].value;
    setVoiceType(defaultVoice);
  }, [voiceGender]);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setImageFile(file);
      setPreviewImageUrl(URL.createObjectURL(file));
    } else {
      setImageFile(null);
      setPreviewImageUrl(null);
    }
  };

  const startRecording = async () => {
    setError(null);
    stopAllAudio(); // Stop any ongoing audio playback

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      setAudioStream(stream);
      setIsRecording(true);
      setAudioChunks([]); // Clear previous chunks

      // Initialize AudioContext and ScriptProcessor for real-time processing
      // Initializes a new AudioContext for input audio, ensuring deprecated `window.webkitAudioContext` is not used.
      inputAudioContextRef.current =
        inputAudioContextRef.current || new window.AudioContext({ sampleRate: AUDIO_SAMPLE_RATE });
      const input = inputAudioContextRef.current;

      const source = input.createMediaStreamSource(stream);
      scriptProcessorRef.current = input.createScriptProcessor(4096, 1, 1);

      scriptProcessorRef.current.onaudioprocess = (audioProcessingEvent) => {
        const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
        setAudioChunks((prev) => [...prev, new Float32Array(inputData)]);

        // Send to Live API if session is active
        if (liveSessionRef.current) {
          liveSessionRef.current.then((session) => {
            session.sendRealtimeInput({ media: createAudioBlob(inputData, AUDIO_SAMPLE_RATE) });
          });
        }
      };

      source.connect(scriptProcessorRef.current);
      scriptProcessorRef.current.connect(input.destination);

      // Start Live API session
      const ai = getGenAIInstance();
      const outputAudioContext = getOutputAudioContext();
      let nextStartTime = 0; // Local for this recording session

      liveSessionRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            console.debug('Live session opened');
            // If message is pre-filled, send it as initial input
            if (message) {
              liveSessionRef.current?.then((session) => {
                session.sendRealtimeInput({ text: message });
              });
            }
          },
          onmessage: async (msg: LiveServerMessage) => {
            // Process model's audio output
            const base64Audio =
              msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioBuffer = await decodeAudioData(
                decode(base64Audio),
                outputAudioContext,
                OUTPUT_AUDIO_SAMPLE_RATE,
                1
              );
              // Use a local nextStartTime for sequential playback within this stream
              nextStartTime = Math.max(nextStartTime, outputAudioContext.currentTime);
              const source = outputAudioContext.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputAudioContext.destination);
              source.start(nextStartTime);
              nextStartTime += audioBuffer.duration;
            }

            // Update transcription in the message input field (optional, but good for UX)
            if (msg.serverContent?.inputTranscription?.text) {
              setMessage(msg.serverContent.inputTranscription.text);
            }
          },
          onerror: (e: ErrorEvent) => {
            console.error('Live session error:', e);
            setError(`Microphone error: ${e.message}`);
            stopRecording();
          },
          onclose: (e: CloseEvent) => {
            console.debug('Live session closed');
          },
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: getVoiceConfig(voiceGender, voiceType),
          },
          inputAudioTranscription: {}, // Enable transcription for user input
        },
      });
    } catch (err: any) {
      console.error('Error starting recording:', err);
      setError(`Failed to start microphone: ${err.message}. Please ensure microphone access is granted.`);
      setIsRecording(false);
    }
  };

  const stopRecording = useCallback(() => {
    setIsRecording(false);
    if (audioStream) {
      audioStream.getTracks().forEach((track) => track.stop());
      setAudioStream(null);
    }
    if (inputAudioContextRef.current) {
      if (scriptProcessorRef.current) {
        scriptProcessorRef.current.disconnect();
        scriptProcessorRef.current = null;
      }
      // inputAudioContextRef.current.close(); // Don't close immediately to avoid issues if restarting quickly
      // inputAudioContextRef.current = null;
    }
    if (liveSessionRef.current) {
      liveSessionRef.current.then((session: any) => session.close());
      liveSessionRef.current = null;
    }
  }, [audioStream]);

  // Cleanup on component unmount
  useEffect(() => {
    return () => {
      stopRecording();
    };
  }, [stopRecording]);

  const generateGreeting = async () => {
    setError(null);
    stopAllAudio();
    if (!message.trim()) {
      setError('Please type a message or speak into the microphone.');
      return;
    }

    try {
      setLoadingAudio(true);
      setLoadingVideo(true);
      const ai = getGenAIInstance();
      let uploadedImageUrl: string | undefined;

      if (imageFile) {
        setVideoGenerationMessage('Uploading image...');
        uploadedImageUrl = await firebaseService.uploadImage(imageFile);
      }

      setVideoGenerationMessage('Generating audio for your message...');
      // 1. Generate Audio (Text-to-Speech)
      const audioResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: message }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: getVoiceConfig(voiceGender, voiceType),
          },
        },
      });

      const base64Audio = audioResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) {
        throw new Error('Could not generate audio from message.');
      }
      // Store as data URL for immediate playback in GreetingCard
      const audioUrl = `data:audio/pcm;base64,${base64Audio}`; 
      console.log(`Generated audio base64 string length: ${base64Audio.length}`);


      setLoadingAudio(false);
      setVideoGenerationMessage('Audio generated. Now generating cinematic video (this video does not include embedded audio, it plays alongside). This may take a few minutes...');

      // 2. Generate Video
      await onApiKeyPrompt(); // Ensure API key is selected before generating video

      const videoPrompt = VIDEO_BACKGROUND_PROMPTS[occasion] || VIDEO_BACKGROUND_PROMPTS.Default;
      const veoModel = 'veo-3.1-fast-generate-preview'; // Default for general video generation
      let operation;

      const baseVideoPayload = {
        model: veoModel,
        prompt: videoPrompt,
        // Removed `audio` field as the `generateVideos` method for Veo models
        // does not currently support embedding audio directly.
        // Audio will be played alongside the video on the client-side.
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9',
        },
      };

      let videoGenerationRequest;

      // For more complex scenarios, prompt can be combined with image
      if (uploadedImageUrl) {
        const imageBytes = (await fetch(uploadedImageUrl).then(res => res.blob()).then(blobToBase64)); // Convert back to base64 for API
        videoGenerationRequest = {
          ...baseVideoPayload,
          image: {
            imageBytes: imageBytes,
            mimeType: imageFile!.type,
          },
        };
      } else {
        videoGenerationRequest = baseVideoPayload;
      }

      console.log("Sending video generation request payload:", videoGenerationRequest);
      operation = await ai.models.generateVideos(videoGenerationRequest);


      while (!operation.done) {
        setVideoGenerationMessage(`Generating video... Please wait (status: ${operation.metadata?.state || 'in progress'}). Note: The video itself will not contain embedded audio.`);
        await new Promise((resolve) => setTimeout(resolve, 10000)); // Poll every 10 seconds
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (!downloadLink) {
        throw new Error('Could not generate video.');
      }

      // The downloadLink needs the API key appended for fetching in a browser environment
      const videoUrl = `${downloadLink}&key=${process.env.API_KEY}`;

      setVideoGenerationMessage(null);
      setLoadingVideo(false);

      // 3. Save Greeting to Firebase
      const newGreeting: Omit<Greeting, 'id' | 'createdAt'> = {
        occasion,
        message,
        imageUrl: uploadedImageUrl,
        audioUrl, // Save the audio URL separately
        videoUrl,
        voiceGender,
        voiceType,
      };
      const savedGreeting = await firebaseService.addGreeting(newGreeting);
      onGreetingCreated(savedGreeting);
      resetForm(); // Clear the form after successful creation
    } catch (e: any) {
      console.error('Error generating greeting:', e);
      setError(`Failed to generate greeting: ${e.message}. If generating a video, ensure a paid API key is selected.`);
      // If "Requested entity was not found", it means API key might be invalid or not selected.
      if (e.message.includes("Requested entity was not found.")) {
        onApiKeyPrompt();
      }
    } finally {
      setLoadingAudio(false);
      setLoadingVideo(false);
      setVideoGenerationMessage(null);
    }
  };

  const isGenerating = loadingAudio || loadingVideo;

  return (
    <div className="bg-gray-800 p-6 md:p-8 rounded-lg shadow-lg mb-8">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Occasion */}
        <div>
          <label htmlFor="occasion" className="block text-gray-300 text-sm font-bold mb-2">
            Occasion
          </label>
          <select
            id="occasion"
            className="shadow appearance-none border border-gray-600 rounded w-full py-2 px-3 bg-gray-700 text-white leading-tight focus:outline-none focus:shadow-outline focus:border-indigo-500"
            value={occasion}
            onChange={(e) => setOccasion(e.target.value)}
            disabled={isGenerating}
          >
            {GREETING_OCCASIONS.map((o) => (
              <option key={o} value={o}>
                {o}
              </option>
            ))}
          </select>
        </div>

        {/* Voice Gender */}
        <div>
          <label htmlFor="voiceGender" className="block text-gray-300 text-sm font-bold mb-2">
            Voice Gender
          </label>
          <select
            id="voiceGender"
            className="shadow appearance-none border border-gray-600 rounded w-full py-2 px-3 bg-gray-700 text-white leading-tight focus:outline-none focus:shadow-outline focus:border-indigo-500"
            value={voiceGender}
            onChange={(e) => setVoiceGender(e.target.value as VoiceGender)}
            disabled={isGenerating}
          >
            {Object.values(VoiceGender).map((gender) => (
              <option key={gender} value={gender}>
                {gender}
              </option>
            ))}
          </select>
        </div>

        {/* Voice Type */}
        <div>
          <label htmlFor="voiceType" className="block text-gray-300 text-sm font-bold mb-2">
            Voice Type
          </label>
          <select
            id="voiceType"
            className="shadow appearance-none border border-gray-600 rounded w-full py-2 px-3 bg-gray-700 text-white leading-tight focus:outline-none focus:shadow-outline focus:border-indigo-500"
            value={voiceType}
            onChange={(e) => setVoiceType(e.target.value as VoiceType)}
            disabled={isGenerating}
          >
            {VOICE_OPTIONS[voiceGender].map((type) => (
              <option key={type.value} value={type.value}>
                {type.label}
              </option>
            ))}
          </select>
        </div>

        {/* Image Upload */}
        <div>
          <label htmlFor="imageUpload" className="block text-gray-300 text-sm font-bold mb-2">
            Upload Image (Optional)
          </label>
          <input
            id="imageUpload"
            type="file"
            accept="image/*"
            className="block w-full text-sm text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-violet-50 file:text-violet-700 hover:file:bg-violet-100 bg-gray-700 rounded-md cursor-pointer focus:outline-none"
            onChange={handleImageChange}
            disabled={isGenerating}
            aria-describedby="image-upload-description"
          />
          <p id="image-upload-description" className="text-xs text-gray-500 mt-1">
            Max file size: 5MB. The image will be incorporated into the visual background of the video. The generated audio will play alongside the video; the image will not lip-sync.
          </p>
          {previewImageUrl && (
            <div className="mt-4">
              <img src={previewImageUrl} alt="Preview" className="max-w-xs h-auto rounded-md shadow-md mx-auto" />
            </div>
          )}
        </div>
      </div>

      {/* Message Input */}
      <div className="mt-6">
        <label htmlFor="message" className="block text-gray-300 text-sm font-bold mb-2">
          Your Message ({message.length}/{MAX_MESSAGE_LENGTH} words)
        </label>
        <textarea
          id="message"
          className="shadow appearance-none border border-gray-600 rounded w-full py-2 px-3 bg-gray-700 text-white leading-tight focus:outline-none focus:shadow-outline focus:border-indigo-500 h-32 resize-y"
          placeholder="Type your heartfelt message here..."
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          maxLength={MAX_MESSAGE_LENGTH}
          disabled={isGenerating || isRecording}
          aria-describedby="message-help-text"
        ></textarea>
        <p id="message-help-text" className="text-xs text-gray-500 mt-1">
          You can type your message or use the microphone.
        </p>
      </div>

      {/* Microphone Input */}
      <div className="mt-4 flex flex-col sm:flex-row gap-4 justify-center items-center">
        <Button
          onClick={isRecording ? stopRecording : startRecording}
          variant={isRecording ? 'danger' : 'secondary'}
          disabled={isGenerating}
          className="flex items-center justify-center w-full sm:w-auto"
          aria-label={isRecording ? 'Stop recording message' : 'Start recording message'}
        >
          {isRecording ? (
            <>
              <svg className="animate-pulse h-5 w-5 mr-2" viewBox="0 0 24 24" fill="currentColor">
                <circle cx="12" cy="12" r="8" />
              </svg>
              Stop Recording
            </>
          ) : (
            <>
              <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                <path
                  fillRule="evenodd"
                  d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z"
                  clipRule="evenodd"
                />
              </svg>
              Record Message
            </>
          )}
        </Button>
      </div>

      {error && (
        <div
          className="bg-red-900 border border-red-700 text-red-200 px-4 py-3 rounded relative mt-6"
          role="alert"
        >
          <strong className="font-bold">Error:</strong>
          <span className="block sm:inline ml-2">{error}</span>
        </div>
      )}

      {videoGenerationMessage && (
        <div
          className="bg-blue-900 border border-blue-700 text-blue-200 px-4 py-3 rounded relative mt-6"
          role="status"
          aria-live="polite"
        >
          <strong className="font-bold">Processing:</strong>
          <span className="block sm:inline ml-2">{videoGenerationMessage}</span>
        </div>
      )}

      <div className="mt-8 flex flex-col sm:flex-row gap-4 justify-center">
        <Button
          onClick={generateGreeting}
          loading={isGenerating}
          disabled={message.length === 0}
          fullWidth
          aria-label="Generate greeting video and audio"
        >
          Generate Greeting
        </Button>
        <Button
          onClick={resetForm}
          variant="secondary"
          disabled={isGenerating}
          fullWidth
          aria-label="Refresh and start a new greeting"
        >
          Refresh/Restart
        </Button>
      </div>
    </div>
  );
};

export default GreetingForm;

// Helper to convert Blob to base64 for image upload to GenAI
const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      resolve(result.split(',')[1]); // Extract base64 part
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

import React, { useState, useEffect, useCallback } from 'react';
import GreetingForm from './components/GreetingForm';
import GreetingList from './components/GreetingList';
import { Greeting } from './types';
import * as firebaseService from './services/firebaseService';
import { GoogleGenAI } from '@google/genai';
import Modal from './components/Modal';
import SharedGreetingPlayer from './components/SharedGreetingPlayer'; // New import

function App() {
  const [greetings, setGreetings] = useState<Greeting[]>([]);
  const [loading, setLoading] = useState(true);
  const [apiKeyModalOpen, setApiKeyModalOpen] = useState(false);
  const [sharedGreetingId, setSharedGreetingId] = useState<string | null>(null);

  // Initialize Firebase on component mount
  useEffect(() => {
    firebaseService.initFirebase();
  }, []);

  // Check URL for shared greeting ID
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get('greetingId');
    setSharedGreetingId(id);
  }, []);

  const fetchGreetings = useCallback(async () => {
    setLoading(true);
    try {
      const fetchedGreetings = await firebaseService.getGreetings();
      setGreetings(fetchedGreetings);
    } catch (error) {
      console.error("Error fetching greetings:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    // Only fetch greetings if not viewing a shared greeting
    if (!sharedGreetingId) {
      fetchGreetings();
    }
  }, [fetchGreetings, sharedGreetingId]);

  const handleGreetingCreated = useCallback((newGreeting: Greeting) => {
    setGreetings((prev) => [...prev, newGreeting]);
  }, []);

  const handleDeleteGreeting = useCallback(async (id: string) => {
    try {
      await firebaseService.deleteGreeting(id);
      setGreetings((prev) => prev.filter((greeting) => greeting.id !== id));
    } catch (error) {
      console.error("Error deleting greeting:", error);
    }
  }, []);

  const checkAndPromptApiKey = useCallback(async () => {
    if (typeof window.aistudio !== 'undefined' && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setApiKeyModalOpen(true);
      }
    }
  }, []);

  useEffect(() => {
    checkAndPromptApiKey();
  }, [checkAndPromptApiKey]);

  const handleOpenApiKeySelection = useCallback(async () => {
    if (typeof window.aistudio !== 'undefined' && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      // Assume success and close modal
      setApiKeyModalOpen(false);
    }
  }, []);

  // Provide an instance of GoogleGenAI to components, created right before use
  const getGenAIInstance = useCallback(() => {
    // CRITICAL: Create new GoogleGenAI instance right before an API call
    // to ensure it uses the most up-to-date API key from the dialog.
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }, []);

  // Conditional rendering based on sharedGreetingId
  if (sharedGreetingId) {
    return (
      <div className="container mx-auto p-4 md:p-8">
        <SharedGreetingPlayer greetingId={sharedGreetingId} />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-4 md:p-8">
      <h1 className="text-4xl md:text-5xl font-extrabold text-center mb-8 text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-green-300">
        e-Greetz
      </h1>

      <GreetingForm
        onGreetingCreated={handleGreetingCreated}
        getGenAIInstance={getGenAIInstance}
        onApiKeyPrompt={checkAndPromptApiKey}
      />

      <hr className="my-10 border-t-2 border-gray-600" />

      <h2 className="text-3xl font-bold text-center mb-6 text-blue-300">Your Created Greetings</h2>
      {loading ? (
        <div className="text-center text-lg text-gray-400">Loading greetings...</div>
      ) : greetings.length === 0 ? (
        <div className="text-center text-lg text-gray-400">No greetings yet. Create one above!</div>
      ) : (
        <GreetingList greetings={greetings} onDelete={handleDeleteGreeting} />
      )}

      <Modal isOpen={apiKeyModalOpen} onClose={() => setApiKeyModalOpen(false)} title="API Key Required">
        <p className="text-gray-200 mb-4">
          To generate cinematic videos, a paid API key from a Google Cloud Project is required.
          Please select or create an API key with billing enabled.
        </p>
        <p className="text-gray-300 mb-4 text-sm">
          For more information on billing, visit{' '}
          <a
            href="https://ai.google.dev/gemini-api/docs/billing"
            target="_blank"
            rel="noopener noreferrer"
            className="text-blue-400 hover:underline"
          >
            ai.google.dev/gemini-api/docs/billing
          </a>
        </p>
        <button
          onClick={handleOpenApiKeySelection}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-md transition-colors duration-200"
        >
          Select API Key
        </button>
      </Modal>
    </div>
  );
}

export default App;

import { initializeApp, FirebaseApp } from 'firebase/app';
import { getFirestore, collection, addDoc, getDocs, deleteDoc, doc, query, orderBy, serverTimestamp, getDoc } from 'firebase/firestore';
import { getStorage, ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { Greeting } from '../types';

// Firebase configuration using environment variables
// These variables must be defined in your .env file (Vite will pick them up if prefixed with VITE_)
// and set in your hosting environment (e.g., Render.com environment variables).
const firebaseConfig = {
  apiKey: process.env.VITE_FIREBASE_API_KEY,
  authDomain: process.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: process.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.VITE_FIREBASE_APP_ID,
  measurementId: process.env.VITE_FIREBASE_MEASUREMENT_ID,
};

let app: FirebaseApp;
let db;
let storage;

export const initFirebase = () => {
  if (!app) {
    // Check if essential Firebase config is available
    if (!firebaseConfig.apiKey || !firebaseConfig.projectId) {
      console.error("Firebase configuration is missing essential values. Check your environment variables.");
      // Optionally, throw an error or handle gracefully
      return; 
    }
    app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    storage = getStorage(app);
    console.log("Firebase initialized.");
  }
};

export const addGreeting = async (greeting: Omit<Greeting, 'id' | 'createdAt'>): Promise<Greeting> => {
  try {
    if (!db) throw new Error("Firestore not initialized.");
    const docRef = await addDoc(collection(db, "greetings"), {
      ...greeting,
      createdAt: serverTimestamp(),
    });
    console.log("Document written with ID: ", docRef.id);
    return { id: docRef.id, createdAt: Date.now(), ...greeting };
  } catch (e) {
    console.error("Error adding document: ", e);
    throw e;
  }
};

export const getGreetings = async (): Promise<Greeting[]> => {
  try {
    if (!db) throw new Error("Firestore not initialized.");
    const q = query(collection(db, "greetings"), orderBy("createdAt", "desc"));
    const querySnapshot = await getDocs(q);
    const greetings: Greeting[] = [];
    querySnapshot.forEach((doc) => {
      const data = doc.data();
      greetings.push({
        id: doc.id,
        occasion: data.occasion,
        message: data.message,
        imageUrl: data.imageUrl,
        audioUrl: data.audioUrl,
        videoUrl: data.videoUrl,
        voiceGender: data.voiceGender,
        voiceType: data.voiceType,
        createdAt: data.createdAt?.toMillis ? data.createdAt.toMillis() : Date.now(), // Convert Firestore Timestamp to JS Date ms
      });
    });
    return greetings;
  } catch (e) {
    console.error("Error getting documents: ", e);
    throw e;
  }
};

export const getGreetingById = async (id: string): Promise<Greeting | null> => {
  try {
    if (!db) throw new Error("Firestore not initialized.");
    const docRef = doc(db, "greetings", id);
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      const data = docSnap.data();
      return {
        id: docSnap.id,
        occasion: data.occasion,
        message: data.message,
        imageUrl: data.imageUrl,
        audioUrl: data.audioUrl,
        videoUrl: data.videoUrl,
        voiceGender: data.voiceGender,
        voiceType: data.voiceType,
        createdAt: data.createdAt?.toMillis ? data.createdAt.toMillis() : Date.now(),
      };
    } else {
      console.log("No such document!");
      return null;
    }
  } catch (e) {
    console.error("Error getting document by ID: ", e);
    throw e;
  }
};

export const deleteGreeting = async (id: string): Promise<void> => {
  try {
    if (!db) throw new Error("Firestore not initialized.");
    await deleteDoc(doc(db, "greetings", id));
    console.log("Document successfully deleted!");
  } catch (e) {
    console.error("Error removing document: ", e);
    throw e;
  }
};

export const uploadImage = async (file: File): Promise<string> => {
  try {
    if (!storage) throw new Error("Firebase Storage not initialized.");
    const storageRef = ref(storage, `images/${file.name}-${Date.now()}`);
    const snapshot = await uploadBytes(storageRef, file);
    const downloadURL = await getDownloadURL(snapshot.ref);
    return downloadURL;
  } catch (e) {
    console.error("Error uploading image: ", e);
    throw e;
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Greeting } from '../types';
import Button from './Button';
import { getOutputAudioContext, playAudioBuffer, decodeAudioData, decode, stopAllAudio, createWavBlobFromPCM } from '../utils/audioUtils';
import { OUTPUT_AUDIO_SAMPLE_RATE } from '../constants';

interface GreetingCardProps {
  greeting: Greeting;
  onDelete: (id: string) => void;
}

const GreetingCard: React.FC<GreetingCardProps> = ({ greeting, onDelete }) => {
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [showVideoPlayer, setShowVideoPlayer] = useState(false); // New state for video player visibility
  const [videoPlaybackLoading, setVideoPlaybackLoading] = useState(false); // New state for video loading spinner
  const audioRef = useRef<HTMLAudioElement | null>(null); // For native audio playback (not currently used for PCM)
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [videoError, setVideoError] = useState<string | null>(null);
  const videoLoadTimeoutRef = useRef<number | null>(null);
  const [copied, setCopied] = useState(false); // New state for copy feedback

  // Internal helper to play audio without managing `isPlayingAudio` state directly
  const _playAudioInternal = useCallback(async () => {
    if (!greeting.audioUrl) {
      console.warn("No audio URL available for playback.");
      return;
    }

    // If it's a data URL, decode and play as PCM
    if (greeting.audioUrl.startsWith('data:audio/pcm;base64,')) {
      const base64Audio = greeting.audioUrl.split(',')[1];
      try {
        const audioBuffer = await decodeAudioData(
          decode(base64Audio),
          getOutputAudioContext(),
          OUTPUT_AUDIO_SAMPLE_RATE,
          1
        );
        await playAudioBuffer(audioBuffer); // This manages global audio sources
      } catch (error) {
        console.error('Error playing PCM audio internally:', error);
        throw error;
      }
    } else {
      // Fallback for standard audio formats if ever generated (not current setup)
      if (audioRef.current) {
        audioRef.current.src = greeting.audioUrl;
        await audioRef.current.play().catch(e => {
          console.error("Error playing audio internally (native):", e);
          throw e;
        });
      }
    }
  }, [greeting.audioUrl]);

  // Function to play/pause audio (for standalone audio button)
  const handlePlayAudio = useCallback(async () => {
    stopAllAudio(); // Stop all existing audio, including any video-synced audio
    if (videoRef.current && !videoRef.current.paused) {
      videoRef.current.pause(); // Pause video if playing
    }
    setVideoError(null); // Clear video error if playing audio separately
    setIsPlayingAudio(true);
    setShowVideoPlayer(false); // Hide video player if audio is played separately
    setVideoPlaybackLoading(false); // Ensure video loading is off

    try {
      await _playAudioInternal();
    } catch (e) {
      setIsPlayingAudio(false);
      console.error("Failed to play audio:", e);
    }
    // We don't set isPlayingAudio to false here on audio `ended` event.
    // This is handled by a global listener in `audioUtils.ts` or when another media starts/stops.
  }, [_playAudioInternal]);

  const handlePauseAudio = useCallback(() => {
    stopAllAudio(); // Stop custom PCM playback
    if (audioRef.current) {
      audioRef.current.pause(); // Stop native HTML audio
    }
    setIsPlayingAudio(false);
  }, []);

  // Function to play video and simultaneously start audio
  const handlePlayVideo = useCallback(async () => {
    stopAllAudio(); // Stop any standalone audio playback
    if (audioRef.current) {
      audioRef.current.pause(); // Stop native HTML audio
    }
    setIsPlayingAudio(false); // Reset audio state
    setVideoError(null); // Clear previous video error
    setShowVideoPlayer(true); // Show the video player
    setVideoPlaybackLoading(true); // Start video loading spinner

    // Clear any previous timeout
    if (videoLoadTimeoutRef.current) {
      clearTimeout(videoLoadTimeoutRef.current);
      videoLoadTimeoutRef.current = null;
    }

    // A small delay to ensure the video element is rendered before attempting to load
    setTimeout(() => {
      if (videoRef.current) {
        const videoElement = videoRef.current;
        videoElement.load(); // Ensure video is loaded

        const startBothPlayback = async () => {
          if (videoLoadTimeoutRef.current) {
            clearTimeout(videoLoadTimeoutRef.current);
            videoLoadTimeoutRef.current = null;
          }
          setVideoPlaybackLoading(false); // Hide loading spinner

          // Start audio first
          if (greeting.audioUrl) {
            try {
              await _playAudioInternal();
            } catch (e) {
              console.error("Error starting synchronized audio for video:", e);
              // Don't block video playback, but log the error
            }
          }

          // Then start video
          videoElement.play().catch(e => {
            console.error("Error playing video:", e);
            setVideoError(`Could not play video: ${e.message}. Ensure your browser allows autoplay or try clicking play manually.`);
          });
          videoElement.requestFullscreen().catch(e => {
            console.warn("Could not enter fullscreen:", e);
          });
        };

        const onVideoCanPlayThrough = () => {
          videoElement.removeEventListener('canplaythrough', onVideoCanPlayThrough);
          startBothPlayback();
        };

        videoElement.addEventListener('canplaythrough', onVideoCanPlayThrough);

        // Fallback timeout in case 'canplaythrough' doesn't fire or takes too long
        videoLoadTimeoutRef.current = window.setTimeout(() => {
          videoElement.removeEventListener('canplaythrough', onVideoCanPlayThrough);
          console.warn("Video 'canplaythrough' timeout, attempting to play anyway.");
          startBothPlayback();
        }, 10000); // 10 seconds timeout
      }
    }, 50); // Small initial delay to ensure render
  }, [greeting.audioUrl, _playAudioInternal]);


  const handleCloseVideoPlayer = useCallback(() => {
    if (videoLoadTimeoutRef.current) {
      clearTimeout(videoLoadTimeoutRef.current);
      videoLoadTimeoutRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.pause(); // Pause video when closing
      // Ensure the 'canplaythrough' listener is removed if it was pending
      videoRef.current.removeEventListener('canplaythrough', () => {}); // Remove any pending listeners
      if (document.fullscreenElement === videoRef.current) {
        document.exitFullscreen().catch(e => console.warn("Could not exit fullscreen:", e));
      }
    }
    stopAllAudio(); // Stop any audio that was playing with the video
    if (audioRef.current) {
      audioRef.current.pause(); // Stop native HTML audio
    }
    setIsPlayingAudio(false); // Reset audio state
    setShowVideoPlayer(false);
    setVideoPlaybackLoading(false); // Reset video loading state
    setVideoError(null);
  }, []);

  useEffect(() => {
    // Event listener for native <audio> element to update state (if ever used)
    const audioEl = audioRef.current;
    if (audioEl) {
      const onEnded = () => setIsPlayingAudio(false);
      const onPlay = () => setIsPlayingAudio(true);
      const onPause = () => setIsPlayingAudio(false);
      audioEl.addEventListener('ended', onEnded);
      audioEl.addEventListener('play', onPlay);
      audioEl.addEventListener('pause', onPause);
      return () => {
        audioEl.removeEventListener('ended', onEnded);
        audioEl.removeEventListener('play', onPlay);
        audioEl.removeEventListener('pause', onPause);
      };
    }

    // Cleanup video player state if greeting changes or component unmounts
    return () => {
      handleCloseVideoPlayer(); // Ensure video is paused and hidden
    };
  }, [greeting.id, handleCloseVideoPlayer]); // Re-run effect if greeting ID changes

  const formattedDate = new Date(greeting.createdAt).toLocaleString();

  // Handle video loading errors
  const handleVideoError = useCallback((event: React.SyntheticEvent<HTMLVideoElement, Event>) => {
    console.error("Video element error:", event);
    setVideoError("Failed to load video. It might be unavailable or corrupt, or network issues prevented loading. The AI-generated video does not include embedded audio; the audio plays alongside.");
    setVideoPlaybackLoading(false); // Hide loading spinner on error
    setShowVideoPlayer(true); // Keep player visible to show error message
  }, []);

  const handleDownloadVideo = useCallback(() => {
    if (greeting.videoUrl) {
      const link = document.createElement('a');
      link.href = greeting.videoUrl;
      link.download = `eGreetz_video_${greeting.id}.mp4`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  }, [greeting.videoUrl, greeting.id]);

  const handleDownloadAudio = useCallback(() => {
    if (greeting.audioUrl && greeting.audioUrl.startsWith('data:audio/pcm;base64,')) {
      try {
        const base64Audio = greeting.audioUrl.split(',')[1];
        const pcmData = decode(base64Audio);
        const wavBlob = createWavBlobFromPCM(pcmData, OUTPUT_AUDIO_SAMPLE_RATE, 1);

        const link = document.createElement('a');
        link.href = URL.createObjectURL(wavBlob);
        link.download = `eGreetz_audio_${greeting.id}.wav`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(link.href); // Clean up the Blob URL
      } catch (error) {
        console.error('Error downloading audio:', error);
        alert('Failed to download audio. Please try again.');
      }
    } else {
      alert('No downloadable audio available in the correct format.');
    }
  }, [greeting.audioUrl, greeting.id]);

  const handleShareGreeting = useCallback(() => {
    if (greeting.id) {
      const shareUrl = `${window.location.origin}${window.location.pathname}?greetingId=${greeting.id}`;
      navigator.clipboard.writeText(shareUrl).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000); // Reset "Copied!" message after 2 seconds
      }).catch(err => {
        console.error('Failed to copy URL:', err);
        alert('Failed to copy URL. Please copy it manually: ' + shareUrl);
      });
    }
  }, [greeting.id]);

  return (
    <div className="relative bg-gray-800 rounded-lg shadow-xl p-6 mb-6 border border-gray-700 overflow-hidden">
      <h3 className="text-3xl font-bold text-center text-indigo-300 mb-4">{greeting.occasion}</h3>
      <p className="text-gray-300 text-center text-sm mb-2">Created: {formattedDate}</p>

      {greeting.imageUrl && (
        <div className="mb-4 flex justify-center">
          <img
            src={greeting.imageUrl}
            alt="User Upload"
            className="max-w-full h-auto max-h-64 object-cover rounded-md shadow-md border border-gray-600"
            loading="lazy"
          />
        </div>
      )}

      <p className="text-gray-200 text-lg mb-4 text-center">{greeting.message}</p>

      <div className="flex flex-col sm:flex-row justify-center gap-4 mt-4">
        {greeting.audioUrl && (
          <Button onClick={isPlayingAudio ? handlePauseAudio : handlePlayAudio} className="w-full sm:w-auto">
            {isPlayingAudio ? (
              <>
                <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg> Pause Audio
              </>
            ) : (
              <>
                <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                </svg> Play Audio
              </>
            )}
          </Button>
        )}

        {greeting.videoUrl && (
          <Button
            onClick={handlePlayVideo} // Use the new handler
            className="w-full sm:w-auto"
            aria-controls={`video-player-${greeting.id}`}
            disabled={videoPlaybackLoading} // Disable button while loading
          >
            {videoPlaybackLoading ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg> Loading Video...
              </>
            ) : (
              <>
                <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path d="M2 6a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2h-4a2 2 0 01-2-2V6zM2 14a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2H4a2 2 0 01-2-2v-2zM14 14a2 2 0 012-2h4a2 2 0 012 2v2a2 2 0 01-2 2h-4a2 2 0 01-2-2v-2z" />
                </svg>
                Play Cinematic Video
              </>
            )}
          </Button>
        )}
      </div>

      {showVideoPlayer && greeting.videoUrl && (
        <div className="mt-4 p-4 bg-gray-900 rounded-lg relative min-h-[200px] flex items-center justify-center">
          {videoPlaybackLoading && (
            <div className="absolute inset-0 bg-gray-800 bg-opacity-90 flex flex-col items-center justify-center rounded-lg z-10">
              <svg className="animate-spin h-8 w-8 text-white mb-3" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <p className="text-white text-lg">Buffering video for synchronized playback...</p>
              <p className="text-gray-400 text-sm mt-1">This ensures audio and video start together. Note: The video itself does not contain embedded audio.</p>
            </div>
          )}
          {videoError && (
            <div className="absolute inset-0 bg-red-900 bg-opacity-90 border border-red-700 text-red-200 px-4 py-3 rounded-lg flex flex-col items-center justify-center text-center z-10" role="alert">
              <strong className="font-bold">Video Error:</strong>
              <span className="block sm:inline ml-2">{videoError}</span>
              <p className="text-sm mt-2">The AI-generated video does not include embedded audio. The audio plays simultaneously alongside the video. Please check your browser's console for more details.</p>
              <button
                onClick={handleCloseVideoPlayer}
                className="mt-4 bg-gray-700 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded-md transition-colors duration-200"
                aria-label="Close error message"
              >
                Close Error
              </button>
            </div>
          )}
          <video
            ref={videoRef}
            id={`video-player-${greeting.id}`}
            src={greeting.videoUrl}
            controls
            className={`w-full max-w-lg mx-auto rounded-md shadow-lg ${videoPlaybackLoading || videoError ? 'invisible' : ''}`}
            aria-label="Cinematic greeting video player"
            onError={handleVideoError}
            preload="auto" // Suggest browser to preload video
          ></video>
          <div className="flex justify-center mt-4">
            <Button
              onClick={handleCloseVideoPlayer}
              variant="secondary"
              className="w-full sm:w-auto"
              aria-label="Close video player"
              disabled={videoPlaybackLoading}
            >
              Close Video
            </Button>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-center gap-4 mt-6 border-t border-gray-700 pt-6">
        {greeting.videoUrl && (
          <Button
            onClick={handleDownloadVideo}
            variant="secondary"
            className="w-full sm:w-auto"
            aria-label="Download generated video"
            title="Download Video (No Audio)"
          >
            <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L10 11.586l2.293-2.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
              <path fillRule="evenodd" d="M10 2a1 1 0 011 1v7a1 1 0 11-2 0V3a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
            Download Video
          </Button>
        )}
        {greeting.audioUrl && (
          <Button
            onClick={handleDownloadAudio}
            variant="secondary"
            className="w-full sm:w-auto"
            aria-label="Download generated audio"
            title="Download Audio (WAV)"
          >
            <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L10 11.586l2.293-2.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
              <path fillRule="evenodd" d="M10 2a1 1 0 011 1v7a1 1 0 11-2 0V3a1 1 0 011-1z" clipRule="evenodd" />
            </svg>
            Download Audio
          </Button>
        )}
        {greeting.videoUrl && greeting.audioUrl && (
          <Button
            onClick={handleShareGreeting}
            variant="secondary"
            className="w-full sm:w-auto relative"
            aria-label="Share this greeting via link"
            title="Share Greeting"
          >
            <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M13 8V2H7v6H2l8 8 8-8h-5zM2 18h16v2H2v-2z" clipRule="evenodd" />
            </svg>
            {copied ? 'Copied!' : 'Share Greeting'}
          </Button>
        )}
      </div>


      <div className="absolute bottom-2 left-2 text-gray-500 text-xs italic opacity-80">
        created by e-Greetz
      </div>

      <Button
        onClick={() => greeting.id && onDelete(greeting.id)}
        variant="danger"
        className="absolute top-4 right-4 p-2 rounded-full text-sm"
        aria-label={`Delete greeting for ${greeting.occasion}`}
        title="Delete Greeting"
      >
        <svg className="h-4 w-4" fill="currentColor" viewBox="0 0 20 20">
          <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm6 0a1 1 0 11-2 0v6a1 1 0 112 0V8z" clipRule="evenodd" />
        </svg>
      </Button>
      {/* Hidden audio element for browser's native controls (e.g., for non-PCM audio, not currently used) */}
      <audio ref={audioRef} className="hidden" onEnded={() => setIsPlayingAudio(false)}></audio>
    </div>
  );
};

export default GreetingCard;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as firebaseService from '../services/firebaseService';
import { Greeting } from '../types';
import Button from './Button';
import { decode, decodeAudioData, getOutputAudioContext, playAudioBuffer, stopAllAudio, createWavBlobFromPCM } from '../utils/audioUtils';
import { OUTPUT_AUDIO_SAMPLE_RATE } from '../constants';

interface SharedGreetingPlayerProps {
  greetingId: string;
}

const SharedGreetingPlayer: React.FC<SharedGreetingPlayerProps> = ({ greetingId }) => {
  const [greeting, setGreeting] = useState<Greeting | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [videoPlaybackLoading, setVideoPlaybackLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false); // Controls combined playback
  const [autoplayAttempted, setAutoplayAttempted] = useState(false);

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const videoLoadTimeoutRef = useRef<number | null>(null);

  const fetchGreeting = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const fetchedGreeting = await firebaseService.getGreetingById(greetingId);
      if (fetchedGreeting) {
        setGreeting(fetchedGreeting);
      } else {
        setError("Greeting not found.");
      }
    } catch (e: any) {
      console.error("Error fetching shared greeting:", e);
      setError(`Failed to load greeting: ${e.message}`);
    } finally {
      setLoading(false);
    }
  }, [greetingId]);

  useEffect(() => {
    fetchGreeting();
  }, [fetchGreeting]);

  const _playAudioInternal = useCallback(async () => {
    if (!greeting?.audioUrl) {
      console.warn("No audio URL available for playback.");
      return;
    }

    if (greeting.audioUrl.startsWith('data:audio/pcm;base64,')) {
      const base64Audio = greeting.audioUrl.split(',')[1];
      try {
        const audioBuffer = await decodeAudioData(
          decode(base64Audio),
          getOutputAudioContext(),
          OUTPUT_AUDIO_SAMPLE_RATE,
          1
        );
        await playAudioBuffer(audioBuffer);
      } catch (error) {
        console.error('Error playing PCM audio internally:', error);
        throw error;
      }
    }
  }, [greeting?.audioUrl]);

  const startCombinedPlayback = useCallback(async () => {
    if (!greeting || !greeting.videoUrl || !greeting.audioUrl) {
      setError("Cannot play greeting: missing video or audio.");
      return;
    }

    stopAllAudio(); // Ensure no other audio is playing
    setVideoPlaybackLoading(true);
    setError(null);
    setIsPlaying(false); // Reset playing state initially

    if (videoLoadTimeoutRef.current) {
      clearTimeout(videoLoadTimeoutRef.current);
      videoLoadTimeoutRef.current = null;
    }

    // Small delay to ensure video element is fully rendered if it wasn't
    setTimeout(() => {
      if (videoRef.current) {
        const videoElement = videoRef.current;
        videoElement.load(); // Ensure video is loaded

        const finalizePlaybackStart = async () => {
          if (videoLoadTimeoutRef.current) {
            clearTimeout(videoLoadTimeoutRef.current);
            videoLoadTimeoutRef.current = null;
          }
          setVideoPlaybackLoading(false);

          try {
            await _playAudioInternal();
          } catch (e) {
            console.error("Error starting synchronized audio for video:", e);
          }

          videoElement.play().then(() => {
            setIsPlaying(true);
            videoElement.requestFullscreen().catch(e => console.warn("Could not enter fullscreen:", e));
          }).catch(e => {
            console.error("Error playing video:", e);
            setError(`Could not play video automatically: ${e.message}. Please click the 'Play Greeting' button below.`);
            setIsPlaying(false);
            setAutoplayAttempted(true); // Indicate autoplay failed, show manual play button
          });
        };

        const onVideoCanPlayThrough = () => {
          videoElement.removeEventListener('canplaythrough', onVideoCanPlayThrough);
          finalizePlaybackStart();
        };

        videoElement.addEventListener('canplaythrough', onVideoCanPlayThrough);

        videoLoadTimeoutRef.current = window.setTimeout(() => {
          videoElement.removeEventListener('canplaythrough', onVideoCanPlayThrough);
          console.warn("Video 'canplaythrough' timeout, attempting to play anyway.");
          finalizePlaybackStart();
        }, 10000); // 10 seconds timeout
      }
    }, 50);
  }, [greeting, _playAudioInternal]);

  // Attempt autoplay once greeting is loaded
  useEffect(() => {
    if (greeting && greeting.videoUrl && greeting.audioUrl && !autoplayAttempted && !isPlaying) {
      startCombinedPlayback();
    }
  }, [greeting, startCombinedPlayback, autoplayAttempted, isPlaying]);

  const handleVideoEnded = useCallback(() => {
    setIsPlaying(false);
    stopAllAudio();
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(e => console.warn("Could not exit fullscreen:", e));
    }
  }, []);

  const handleVideoError = useCallback((event: React.SyntheticEvent<HTMLVideoElement, Event>) => {
    console.error("Video element error:", event);
    setError("Failed to load video. It might be unavailable or corrupt, or network issues prevented loading. The AI-generated video does not include embedded audio; the audio plays alongside.");
    setVideoPlaybackLoading(false);
    setIsPlaying(false);
  }, []);

  const handleBackToMainApp = useCallback(() => {
    window.location.href = window.location.origin + window.location.pathname; // Go back to main app
  }, []);


  if (loading) {
    return (
      <div className="text-center text-lg text-gray-400 p-8">
        <svg className="animate-spin mx-auto h-8 w-8 text-white mb-3" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
        Loading Greeting...
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center text-red-400 p-8 bg-gray-800 rounded-lg shadow-xl">
        <h2 className="text-2xl font-bold mb-4">Error</h2>
        <p className="mb-6">{error}</p>
        <Button onClick={handleBackToMainApp} variant="secondary">Back to e-Greetz</Button>
      </div>
    );
  }

  if (!greeting) {
    return (
      <div className="text-center text-gray-400 p-8 bg-gray-800 rounded-lg shadow-xl">
        <h2 className="text-2xl font-bold mb-4">Greeting Not Found</h2>
        <p className="mb-6">The greeting you are looking for does not exist or the link is incorrect.</p>
        <Button onClick={handleBackToMainApp} variant="secondary">Back to e-Greetz</Button>
      </div>
    );
  }

  const formattedDate = new Date(greeting.createdAt).toLocaleString();

  return (
    <div className="relative bg-gray-800 rounded-lg shadow-xl p-6 mb-6 border border-gray-700 overflow-hidden">
      <h1 className="text-4xl md:text-5xl font-extrabold text-center mb-6 text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-green-300">
        e-Greetz
      </h1>
      <h3 className="text-3xl font-bold text-center text-indigo-300 mb-4">{greeting.occasion}</h3>
      <p className="text-gray-300 text-center text-sm mb-2">Created: {formattedDate}</p>

      {greeting.imageUrl && (
        <div className="mb-4 flex justify-center">
          <img
            src={greeting.imageUrl}
            alt="Greeting Visual"
            className="max-w-full h-auto max-h-64 object-cover rounded-md shadow-md border border-gray-600"
            loading="lazy"
          />
        </div>
      )}

      <p className="text-gray-200 text-lg mb-4 text-center">{greeting.message}</p>

      {/* Video Player Section */}
      <div className="mt-4 p-4 bg-gray-900 rounded-lg relative min-h-[200px] flex items-center justify-center">
        {(videoPlaybackLoading || !isPlaying) && (
          <div className="absolute inset-0 bg-gray-800 bg-opacity-90 flex flex-col items-center justify-center rounded-lg z-10">
            {videoPlaybackLoading && (
              <>
                <svg className="animate-spin h-8 w-8 text-white mb-3" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <p className="text-white text-lg">Buffering video for synchronized playback...</p>
                <p className="text-gray-400 text-sm mt-1">This ensures audio and video start together. Note: The video itself does not contain embedded audio.</p>
              </>
            )}
            {!videoPlaybackLoading && !isPlaying && error && (
              <div className="text-red-200 text-center mb-4">{error}</div>
            )}
            {!videoPlaybackLoading && !isPlaying && (
              <Button onClick={startCombinedPlayback}>
                <svg className="h-5 w-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                </svg>
                Play Greeting
              </Button>
            )}
          </div>
        )}
        <video
          ref={videoRef}
          src={greeting.videoUrl}
          controls={isPlaying} // Show controls only when playing, or after manual play is needed
          className={`w-full max-w-lg mx-auto rounded-md shadow-lg ${!isPlaying && !error ? 'invisible' : ''}`}
          aria-label="Cinematic greeting video player"
          onEnded={handleVideoEnded}
          onError={handleVideoError}
          preload="auto"
          muted={!isPlaying} // Mute initially to allow autoplay, then unmute if `play()` succeeds without error
        ></video>
      </div>

      <div className="flex justify-center mt-6">
        <Button onClick={handleBackToMainApp} variant="secondary">Back to e-Greetz</Button>
      </div>

      <div className="absolute bottom-2 left-2 text-gray-500 text-xs italic opacity-80">
        created by e-Greetz
      </div>
    </div>
  );
};

export default SharedGreetingPlayer;
